#ifndef VG_TEXT_FLOAT
#define VG_TEXT_FLOAT
static const char* vg_text_float(double x) {
    if (isnan(x)) return "NaN";
    if (isinf(x)) return x > 0 ? "Infinity" : "-Infinity";
    if (x == 0) return "0";
    char scientific[40];
    for (int precision = 0; precision < 17; precision++) {
        snprintf(scientific, sizeof scientific, "%.*e", precision, fabs(x));
        if (strtod(scientific, NULL) == fabs(x)) break;
    }
    char digits[24];
    int k = 0;
    for (const char* c = scientific; *c && *c != 'e'; c++) if (*c != '.') digits[k++] = *c;
    while (k > 1 && digits[k - 1] == '0') k--;
    digits[k] = '\0';
    int n = atoi(strchr(scientific, 'e') + 1) + 1;
    char text[64];
    int at = 0;
    if (x < 0) text[at++] = '-';
    if (k <= n && n <= 21) {
        at += sprintf(text + at, "%s", digits);
        for (int i = k; i < n; i++) text[at++] = '0';
    } else if (0 < n && n <= 21) {
        at += sprintf(text + at, "%.*s.%s", n, digits, digits + n);
    } else if (-6 < n && n <= 0) {
        at += sprintf(text + at, "0.");
        for (int i = 0; i < -n; i++) text[at++] = '0';
        at += sprintf(text + at, "%s", digits);
    } else {
        at += sprintf(text + at, "%c%s%s", digits[0], k > 1 ? "." : "", digits + 1);
        at += sprintf(text + at, "e%c%d", n - 1 >= 0 ? '+' : '-', abs(n - 1));
    }
    return vg_copy(text, (size_t)at);
}
#endif

