helpers.vg_is_space:
#ifndef VG_IS_SPACE
#define VG_IS_SPACE
static bool vg_is_space(char c) {
    return c == ' ' || (c >= '\t' && c <= '\r');
}
#endif

helpers.vg_length:
#ifndef VG_LENGTH
#define VG_LENGTH
// A length in code points.
static long long vg_length(const char* text) {
    long long length = 0;
    for (const char* p = text; *p; p++) if ((*p & 0xC0) != 0x80) length++;
    return length;
}
#endif

helpers.vg_repeat:
#ifndef VG_REPEAT
#define VG_REPEAT
static const char* vg_repeat(const char* text, long long count) {
    if (count <= 0) return "";
    size_t length = strlen(text);
    char* result = (char*)malloc(length * (size_t)count + 1);
    for (long long i = 0; i < count; i++) memcpy(result + length * (size_t)i, text, length);
    result[length * (size_t)count] = '\0';
    return result;
}
#endif

helpers.vg_words:
#ifndef VG_WORDS
#define VG_WORDS
static bool vg_is_upper(char c) { return c >= 'A' && c <= 'Z'; }
static bool vg_is_lower(char c) { return c >= 'a' && c <= 'z'; }
static bool vg_is_digit(char c) { return c >= '0' && c <= '9'; }
static const char* vg_words(const char* text, const char* separator, bool camel) {
    size_t length = strlen(text), gap = strlen(separator), size = 0, start = 0;
    char* result = (char*)malloc(length * (gap + 1) + 1);
    bool first = true;
    for (size_t i = 0; i <= length; i++) {
        char c = text[i];
        bool letter = vg_is_upper(c) || vg_is_lower(c) || vg_is_digit(c);
        char prev = i > start ? text[i - 1] : '\0';
        if (i > start && (!letter || (vg_is_upper(c) && (vg_is_lower(prev) || vg_is_digit(prev) || (vg_is_upper(prev) && vg_is_lower(text[i + 1])))))) {
            if (!first) {
                memcpy(result + size, separator, gap);
                size += gap;
            }
            for (size_t j = start; j < i; j++) {
                char w = text[j];
                if (vg_is_upper(w)) w = (char)(w + 32);
                if (camel && !first && j == start && vg_is_lower(w)) w = (char)(w - 32);
                result[size++] = w;
            }
            first = false;
            start = i;
        }
        if (!letter) start = i + 1;
    }
    result[size] = '\0';
    return result;
}
#endif

helpers.vg_is_utf8:
#ifndef VG_IS_UTF8
#define VG_IS_UTF8
static bool vg_is_utf8(const char* text, size_t length) {
    const unsigned char* s = (const unsigned char*)text;
    for (size_t i = 0; i < length;) {
        unsigned char c = s[i];
        size_t n = c < 0x80 ? 1 : c >= 0xC2 && c <= 0xDF ? 2 : c >= 0xE0 && c <= 0xEF ? 3 : c >= 0xF0 && c <= 0xF4 ? 4 : 0;
        if (n == 0 || i + n > length) return false;
        unsigned long code = n == 1 ? c : c & (0xFF >> (n + 1));
        for (size_t k = 1; k < n; k++) {
            if ((s[i + k] & 0xC0) != 0x80) return false;
            code = code << 6 | (s[i + k] & 0x3F);
        }
        if ((n == 3 && (code < 0x800 || (code >= 0xD800 && code <= 0xDFFF))) || (n == 4 && (code < 0x10000 || code > 0x10FFFF))) return false;
        i += n;
    }
    return true;
}
#endif

